function l(t){let s=t.reduce((e,r)=>e+Math.max(r.distanceM,0),0)>0,o=t.map(e=>Math.max(s?e.distanceM:e.percentage,0)),c=o.reduce((e,r)=>e+r,0);if(c<=0)return t.map(()=>0);let a=o.map(e=>e/c*100),n=a.map(Math.floor),p=100-n.reduce((e,r)=>e+r,0),u=a.map((e,r)=>({index:r,remainder:e-n[r]})).sort((e,r)=>r.remainder-e.remainder||e.index-r.index);for(let{index:e}of u){if(p<=0)break;n[e]+=1,p-=1}return o.filter(e=>e>0).length>1?n.map(e=>Math.min(e,99)):n}export{l as a};
